package com.lootpop;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

final class LootNotification
{
    private final String sourceName;
    private final List<LootDisplayItem> items;
    private final long totalValue;
    private long visibleAtMillis;
    private long pausedAtMillis = -1L;
    private long pausedDurationMillis;
    private boolean collectionLogUnlock;

    LootNotification(String sourceName, List<LootDisplayItem> items, long totalValue, long createdAtMillis)
    {
        this.sourceName = sourceName;
        this.items = Collections.unmodifiableList(new ArrayList<>(items));
        this.totalValue = totalValue;
        this.visibleAtMillis = createdAtMillis;
    }

    String getSourceName()
    {
        return sourceName;
    }

    List<LootDisplayItem> getItems()
    {
        return items;
    }

    long getTotalValue()
    {
        return totalValue;
    }

    boolean isCollectionLogUnlock()
    {
        return collectionLogUnlock;
    }

    void setCollectionLogUnlock(boolean collectionLogUnlock)
    {
        this.collectionLogUnlock = collectionLogUnlock;
    }

    long getAgeMillis(long nowMillis)
    {
        long effectiveNow = pausedAtMillis >= 0L ? pausedAtMillis : nowMillis;
        return Math.max(0L, effectiveNow - visibleAtMillis - pausedDurationMillis);
    }

    void setHovered(boolean hovered, long nowMillis)
    {
        if (hovered && pausedAtMillis < 0L)
        {
            pausedAtMillis = nowMillis;
        }
        else if (!hovered && pausedAtMillis >= 0L)
        {
            pausedDurationMillis += Math.max(0L, nowMillis - pausedAtMillis);
            pausedAtMillis = -1L;
        }
    }

    void restartAt(long nowMillis)
    {
        visibleAtMillis = nowMillis;
        pausedAtMillis = -1L;
        pausedDurationMillis = 0L;
    }

    float getAlpha(long nowMillis, int displayDuration, int fadeDuration)
    {
        long age = getAgeMillis(nowMillis);
        if (age <= displayDuration)
        {
            return 1.0f;
        }

        if (fadeDuration <= 0)
        {
            return 0.0f;
        }

        float progress = (age - displayDuration) / (float) fadeDuration;
        return Math.max(0.0f, 1.0f - progress);
    }

    boolean isExpired(long nowMillis, int displayDuration, int fadeDuration)
    {
        return getAgeMillis(nowMillis) > (long) displayDuration + fadeDuration;
    }
}

package com.lootpop;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup(LootPopConfig.GROUP)
public interface LootPopConfig extends Config
{
    String GROUP = "lootpop";

    @ConfigSection(
        name = "Appearance",
        description = "Popup layout and background",
        position = 0
    )
    String appearanceSection = "appearance";

    @ConfigSection(
        name = "Behaviour",
        description = "Popup timing and stacking",
        position = 1
    )
    String behaviourSection = "behaviour";

    @ConfigSection(
        name = "Loot filters",
        description = "Choose which drops create a popup",
        position = 2
    )
    String filtersSection = "filters";

    @ConfigSection(
        name = "Value colours",
        description = "Price tiers, colour fade and legendary effects",
        position = 3
    )
    String valueColoursSection = "valueColours";

    @ConfigSection(
        name = "Drop rarity",
        description = "Wiki drop-rate tiers, lucky drops and item spotlighting",
        position = 4
    )
    String dropRaritySection = "dropRarity";

    @ConfigSection(
        name = "Hover details",
        description = "Choose the information shown while hovering an item",
        position = 5,
        closedByDefault = true
    )
    String hoverDetailsSection = "hoverDetails";

    @ConfigSection(
        name = "Colours",
        description = "Popup colours",
        position = 8,
        closedByDefault = true
    )
    String coloursSection = "colours";

    @ConfigSection(
        name = "Tier effects",
        description = "Choose animated effects for each value tier",
        position = 6
    )
    String tierEffectsSection = "tierEffects";

    @ConfigSection(
        name = "Sound & testing",
        description = "Rare-drop sounds and instant popup previews",
        position = 9,
        closedByDefault = true
    )
    String soundTestingSection = "soundTesting";

    @ConfigSection(
        name = "Accessibility",
        description = "Motion, contrast and colour accessibility",
        position = 7,
        closedByDefault = true
    )
    String accessibilitySection = "accessibility";

    @ConfigSection(
        name = "Rare screenshots",
        description = "Optional local screenshots for valuable or rare drops",
        position = 10,
        closedByDefault = true
    )
    String screenshotsSection = "screenshots";

    @ConfigSection(
        name = "Side panel",
        description = "Recent loot and session summary controls",
        position = 11,
        closedByDefault = true
    )
    String sidePanelSection = "sidePanel";

    @ConfigItem(
        keyName = "visualMode",
        name = "Experience mode",
        description = "Performance keeps the original lightweight look; Enhanced enables all visual polish",
        position = 0,
        section = appearanceSection
    )
    default VisualMode visualMode()
    {
        return VisualMode.ENHANCED;
    }

    @ConfigItem(
        keyName = "popupStyle",
        name = "Popup style",
        description = "Choose Classic Frame, Rugged Panel or Loot Strip",
        position = 1,
        section = appearanceSection
    )
    default PopupStyle popupStyle()
    {
        return PopupStyle.CLASSIC_FRAME;
    }

    @ConfigItem(
        keyName = "backgroundMode",
        name = "Background",
        description = "Use a solid or transparent background",
        position = 2,
        section = appearanceSection
    )
    default BackgroundMode backgroundMode()
    {
        return BackgroundMode.SOLID;
    }

    @Range(min = 70, max = 160)
    @ConfigItem(
        keyName = "scale",
        name = "Scale",
        description = "Scale the whole popup",
        position = 3,
        section = appearanceSection
    )
    default int scale()
    {
        return 100;
    }

    @Range(min = 1, max = 12)
    @ConfigItem(
        keyName = "maxItems",
        name = "Visible items",
        description = "Maximum number of item icons shown in each popup",
        position = 4,
        section = appearanceSection
    )
    default int maxItems()
    {
        return 8;
    }

    @ConfigItem(
        keyName = "showShadow",
        name = "Drop shadow",
        description = "Draw a soft shadow behind solid popups",
        position = 5,
        section = appearanceSection
    )
    default boolean showShadow()
    {
        return true;
    }

    @ConfigItem(
        keyName = "showItemTooltips",
        name = "Item hover details",
        description = "Show quantity, GE and high alchemy values, stack value and Wiki drop chance while hovering an icon",
        position = 6,
        section = appearanceSection
    )
    default boolean showItemTooltips()
    {
        return true;
    }

    @ConfigItem(
        keyName = "hoverDetailMode",
        name = "Hover preset",
        description = "Compact shows essentials, Detailed shows everything, and Custom uses the switches below",
        position = 0,
        section = hoverDetailsSection
    )
    default HoverDetailMode hoverDetailMode()
    {
        return HoverDetailMode.DETAILED;
    }

